<script setup lang="ts">
import {Head,Link} from '@inertiajs/vue3';
import AdminLayout from '../../../../../CORE/Resources/js/Layouts/AdminLayout.vue';
import DataTable,{type DataTableColumn} from '../../../../../CORE/Resources/js/Components/DataTable.vue';
import type {Paginator} from '../../../../../CORE/Resources/js/types';
interface Row {id:number;employee_id:string;employee_name:string;unpaid_leave_days:number|string;late_count:number;early_out_count:number;punishment_days:number;punishable:boolean;missing_punch_count:number;unpaid_leave_deduction:number|string;late_penalty_deduction:number|string;missing_punch_deduction:number|string;approved_overtime_minutes:number;approved_extra_duty_minutes:number;overtime_pay:number|string;extra_duty_pay:number|string;source_breakdown:any}
const p=defineProps<{cutlist:any;items:Paginator<Row>}>();
function money(x:unknown){return Number(x||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
const columns:DataTableColumn[]=[{key:'employee_name',label:'Employee',sortable:true},{key:'unpaid_leave_days',label:'Unpaid leave days',align:'right',sortable:true},{key:'unpaid_leave_deduction',label:'Unpaid leave deduction',align:'right'},{key:'late_count',label:'Late',align:'right'},{key:'early_out_count',label:'Early out',align:'right'},{key:'punishment_days',label:'Punishment days',align:'right',sortable:true},{key:'punishable',label:'HRM policy',align:'center'},{key:'late_penalty_deduction',label:'Punishment deduction',align:'right'},{key:'missing_punch_count',label:'Missing punches',align:'right'},{key:'missing_punch_deduction',label:'Missing punch deduction',align:'right'},{key:'approved_overtime_minutes',label:'Approved OT',align:'right'},{key:'overtime_pay',label:'OT pay',align:'right',sortable:true},{key:'approved_extra_duty_minutes',label:'Approved extra duty',align:'right'},{key:'extra_duty_pay',label:'Extra duty pay',align:'right',sortable:true},{key:'source_breakdown',label:'Source detail'}];
</script>
<template><AdminLayout :breadcrumbs="[{title:'PAYROLL'},{title:'Salary Sheets',href:route('payroll.sheets.index')},{title:'Cutlist'}]"><Head title="Salary cutlist"/><div class="mb-4 flex items-center justify-between gap-3"><div><h1 class="text-xl font-bold">Salary cutlist · {{cutlist.pay_year}}-{{String(cutlist.pay_month).padStart(2,'0')}}</h1><p class="text-sm text-muted-foreground">Status: {{cutlist.status}} · generated {{cutlist.generated_at||'—'}}</p></div><Link :href="route('payroll.sheets.index')" class="text-sm text-primary underline">Salary sheets</Link></div><div class="mb-4 rounded-lg border bg-muted/30 p-3 text-sm">Punishment is conditional on employee HRM <code>is_punishable</code>. Payroll salary-sheet mode determines whether the deduction is applied. OT/extra-duty amounts include approved records only.</div><DataTable :route-name="'payroll.cutlists.show'" :route-params="{cutlist:cutlist.id}" title="Employee cutlist and approvals" :columns="columns" :rows="items.data as unknown as Record<string,unknown>[]" :meta="items.meta" :default-sort="{key:'employee_name',direction:'asc'}"><template #cell-employee_name="{row}"><div><strong>{{row.employee_name}}</strong><span class="block text-xs text-muted-foreground">{{row.employee_id}}</span></div></template><template #cell-unpaid_leave_deduction="{row}">{{money(row.unpaid_leave_deduction)}}</template><template #cell-punishable="{row}">{{row.punishable?'Yes':'No'}}</template><template #cell-late_penalty_deduction="{row}">{{money(row.late_penalty_deduction)}}</template><template #cell-missing_punch_deduction="{row}">{{money(row.missing_punch_deduction)}}</template><template #cell-approved_overtime_minutes="{row}">{{(Number(row.approved_overtime_minutes||0)/60).toFixed(2)}} h</template><template #cell-overtime_pay="{row}">{{money(row.overtime_pay)}}</template><template #cell-approved_extra_duty_minutes="{row}">{{(Number(row.approved_extra_duty_minutes||0)/60).toFixed(2)}} h</template><template #cell-extra_duty_pay="{row}">{{money(row.extra_duty_pay)}}</template><template #cell-source_breakdown="{row}"><details class="max-w-72"><summary class="cursor-pointer text-primary">View dates / approvals</summary><pre class="mt-2 max-h-48 overflow-auto whitespace-pre-wrap text-[10px]">{{JSON.stringify(row.source_breakdown||{},null,2)}}</pre></details></template></DataTable></AdminLayout></template>